8:use anyhow::{Context, Result};
9:use crate::method_contract_admission::AdmittedContract;
10:
11:pub(crate) struct RouterCaller {
12:    pub actor: String,
13:    pub capability: Option<String>,
14:    pub session: Option<String>,
15:    pub genesis: Option<String>,
16:}
17:
18:/// Original facade admission carried to the final native operation boundary.
19:/// This is internal evidence, never a wire-supplied identity or grant.
20:#[derive(Clone)]
21:pub(crate) struct FacadeOrigin {
22:    pub plugin: &'static str,
23:    pub method: String,
24:    pub target_plugin: &'static str,
25:    pub target_method: &'static str,
26:    pub admitted: AdmittedContract,
27:    pub capability: String,
28:}
29:
30:impl FacadeOrigin {
31:    pub fn validate_target(&self, plugin: &str, method: &str) -> Result<()> {
32:        anyhow::ensure!(
33:            plugin == self.target_plugin && method == self.target_method,
34:            "facade evidence does not match its target"
35:        );
36:        Ok(())
37:    }
38:
39:    pub async fn readmit(&self, engine: &MutationEngine, caller: &RouterCaller) -> Result<()> {
40:        let outer = RouterCaller {
41:            actor: caller.actor.clone(),
42:            capability: Some(self.capability.clone()),
43:            session: caller.session.clone(),
44:            genesis: caller.genesis.clone(),
45:        };
46:        readmit_call(engine, &self.admitted, self.plugin, &self.method, &outer).await?;
47:        Ok(())
48:    }
49:}
50:
